    description: "\u062F\u06CC\u062F\u06AF\u0627\u0647\u200C\u0647\u0627\u06CC \u0645\u062F\u0631\u0646 \u0627\u0633\u062A\u0631\u0627\u062A\u0698\u06CC\u060C \u0645\u062F\u0644\u200C\u0647\u0627\u06CC \u0645\u0646\u0628\u0639\u200C\u0645\u062D\u0648\u0631 (RBV)\u060C \u0642\u0627\u0628\u0644\u06CC\u062A\u200C\u0647\u0627\u06CC \u067E\u0648\u06CC\u0627\u060C \u0645\u0627\u062A\u0631\u06CC\u0633\u200C\u0647\u0627\u06CC \u067E\u0648\u0631\u062A\u0641\u0648\u0644\u06CC\u0648 \u0648 \u0634\u0627\u06CC\u0633\u062A\u06AF\u06CC\u200C\u0647\u0627\u06CC \u0645\u062D\u0648\u0631\u06CC",
