          "\u0627\u0628\u0647\u0627\u0645 \u0639\u0644\u06CC \u06CC\u0639\u0646\u06CC \u067E\u06CC\u0648\u0646\u062F \u0628\u06CC\u0646 \u0645\u0646\u0628\u0639 \u0648 \u0645\u0632\u06CC\u062A \u0631\u0642\u0627\u0628\u062A\u06CC \u0628\u0647\u200C\u0642\u062F\u0631\u06CC \u067E\u06CC\u0686\u06CC\u062F\u0647 \u0627\u0633\u062A \u06A9\u0647 \u062D\u062A\u06CC \u0645\u062F\u06CC\u0631\u0627\u0646 \u062E\u0648\u062F \u0628\u0646\u06AF\u0627\u0647 \u0647\u0645 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u0646\u062F \u0641\u0631\u0645\u0648\u0644 \u062F\u0642\u06CC\u0642 \u0622\u0646 \u0631\u0627 \u0628\u0647 \u0631\u0642\u0628\u0627 \u062A\u0648\u0636\u06CC\u062D \u062F\u0647\u0646\u062F \u06CC\u0627 \u0628\u0641\u0631\u0648\u0634\u0646\u062F.",
