        chapter: "\u0645\u062F\u06CC\u0631\u06CC\u062A \u062F\u0631 \u0633\u06CC\u0631\u0647 \u0639\u0644\u0648\u06CC",
        topic: "\u0639\u0647\u062F\u0646\u0627\u0645\u0647 \u0645\u0627\u0644\u06A9 \u0627\u0634\u062A\u0631 (\u0646\u0627\u0645\u0647 \u06F5\u06F3 \u0646\u0647\u062C\u200C\u0627\u0644\u0628\u0644\u0627\u063A\u0647) \u0648 \u0646\u0638\u0627\u0645 \u06AF\u0632\u06CC\u0646\u0634 \u0648 \u0646\u0638\u0627\u0631\u062A \u0628\u0631 \u06A9\u0627\u0631\u06AF\u0632\u0627\u0631\u0627\u0646",
        konkoorWeight: "\u0645\u0647\u0645\u200C\u062A\u0631\u06CC\u0646 \u0645\u0646\u0628\u0639 \u062A\u0633\u062A\u200C\u0647\u0627\u06CC \u0645\u062F\u06CC\u0631\u06CC\u062A \u0627\u0633\u0644\u0627\u0645\u06CC (\u062D\u062F\u0627\u0642\u0644 \u06F3\u06F0\u066A \u0633\u0624\u0627\u0644\u0627\u062A)",
        frequency: "\u062A\u06A9\u0631\u0627\u0631 \u0645\u0633\u062A\u0645\u0631 \u062F\u0631 \u062A\u0645\u0627\u0645 \u062F\u0648\u0631\u0647\u200C\u0647\u0627\u06CC \u0622\u0632\u0645\u0648\u0646 \u062F\u06A9\u062A\u0631\u06CC \u0645\u062F\u06CC\u0631\u06CC\u062A",
        summary: `\u0646\u0627\u0645\u0647 \u06F5\u06F3 \u0646\u0647\u062C\u200C\u0627\u0644\u0628\u0644\u0627\u063A\u0647 (\u0641\u0631\u0645\u0627\u0646 \u062D\u0636\u0631\u062A \u0639\u0644\u06CC \u0639 \u0628\u0647 \u0645\u0627\u0644\u06A9 \u0627\u0634\u062A\u0631 \u0646\u062E\u0639\u06CC \u0647\u0646\u06AF\u0627\u0645 \u0627\u0646\u062A\u0635\u0627\u0628 \u0628\u0647 \u0627\u0633\u062A\u0627\u0646\u062F\u0627\u0631\u06CC \u0645\u0635\u0631) \u062C\u0627\u0645\u0639\u200C\u062A\u0631\u06CC\u0646 \u0645\u0646\u0634\u0648\u0631 \u0645\u062F\u06CC\u0631\u06CC\u062A \u062F\u0648\u0644\u062A\u06CC \u0648 \u062D\u06A9\u0645\u0631\u0627\u0646\u06CC \u0627\u0633\u0644\u0627\u0645\u06CC \u0627\u0633\u062A.
\u0645\u062D\u0648\u0631\u0647\u0627\u06CC \u0628\u0646\u06CC\u0627\u062F\u06CC\u0646 \u0639\u0647\u062F\u0646\u0627\u0645\u0647:
\u2022 \u0645\u0639\u06CC\u0627\u0631 \u06AF\u0632\u06CC\u0646\u0634 \u06A9\u0627\u0631\u06AF\u0632\u0627\u0631\u0627\u0646: \u0627\u0641\u0631\u0627\u062F \u0628\u0627 \u062A\u062C\u0631\u0628\u0647\u060C \u0627\u0647\u0644 \u062D\u06CC\u0627 \u0648 \u0639\u0641\u062A \u0646\u0641\u0633\u060C \u0627\u0635\u0627\u0644\u062A \u062E\u0627\u0646\u0648\u0627\u062F\u06AF\u06CC\u060C \u067E\u06CC\u0634\u06AF\u0627\u0645\u0627\u0646 \u062F\u0631 \u062F\u06CC\u0646\u062F\u0627\u0631\u06CC\u060C \u0648 \u0646\u0647 \u0627\u0641\u0631\u0627\u062F \u0641\u0631\u0635\u062A\u200C\u0637\u0644\u0628 \u0648 \u0686\u0627\u067E\u0644\u0648\u0633.
\u2022 \u062A\u0623\u0645\u06CC\u0646 \u0645\u0627\u0644\u06CC \u0645\u062F\u06CC\u0631\u0627\u0646 (\u0627\u0633\u062A\u063A\u0646\u0627\u0621 \u06A9\u0627\u0631\u06AF\u0632\u0627\u0631\u0627\u0646): \u067E\u0631\u062F\u0627\u062E\u062A \u062D\u0642\u0648\u0642 \u0645\u06A9\u0641\u06CC \u0628\u0631\u0627\u06CC \u062C\u0644\u0648\u06AF\u06CC\u0631\u06CC \u0627\u0632 \u062F\u0633\u062A\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u0628\u0647 \u0628\u06CC\u062A\u200C\u0627\u0644\u0645\u0627\u0644.
\u2022 \u0646\u0638\u0627\u0645 \u0646\u0638\u0627\u0631\u062A \u067E\u0646\u0647\u0627\u0646 \u0648 \u0628\u0627\u0632\u0631\u0633\u06CC: \u0628\u0647\u200C\u06A9\u0627\u0631\u06AF\u06CC\u0631\u06CC \u0628\u0627\u0632\u0631\u0633\u0627\u0646 \u0645\u062E\u0641\u06CC\u060C \u0627\u0645\u06CC\u0646 \u0648 \u0631\u0627\u0633\u062A\u06AF\u0648 (\u0639\u064F\u06CC\u0648\u0646) \u0628\u0631\u0627\u06CC \u0631\u0635\u062F \u067E\u06CC\u0648\u0633\u062A\u0647 \u0639\u0645\u0644\u06A9\u0631\u062F \u0639\u0645\u0627\u0644.
\u2022 \u0627\u0635\u0644 \u0639\u062F\u0645 \u0645\u0633\u0627\u0648\u0627\u062A \u0628\u06CC\u0646 \u0646\u06CC\u06A9\u0648\u06A9\u0627\u0631 \u0648 \u0628\u062F\u06A9\u0627\u0631: \u0646\u0628\u0627\u06CC\u062F \u0646\u06CC\u06A9\u0648\u06A9\u0627\u0631 \u0648 \u0628\u062F\u06A9\u0627\u0631 \u062F\u0631 \u067E\u0627\u062F\u0627\u0634 \u06CC\u06A9\u0633\u0627\u0646 \u0628\u0627\u0634\u0646\u062F\u060C \u0632\u06CC\u0631\u0627 \u0627\u06CC\u0646 \u06A9\u0627\u0631 \u0646\u06CC\u06A9\u0648\u06A9\u0627\u0631 \u0631\u0627 \u062F\u0644\u0633\u0631\u062F \u0648 \u0628\u062F\u06A9\u0627\u0631 \u0631\u0627 \u062C\u0631\u06CC\u200C\u062A\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.`,
