        topic: "\u0639\u062F\u0627\u0644\u062A \u0633\u0627\u0632\u0645\u0627\u0646\u06CC \u0648 \u0633\u06CC\u0631\u0647 \u062D\u06A9\u0645\u0631\u0627\u0646\u06CC \u0639\u0644\u0648\u06CC \u062F\u0631 \u062A\u0642\u0633\u06CC\u0645 \u0645\u0633\u0626\u0648\u0644\u06CC\u062A\u200C\u0647\u0627 \u0648 \u0628\u06CC\u062A\u200C\u0627\u0644\u0645\u0627\u0644",
