        frequency: "\u062A\u06A9\u0631\u0627\u0631 \u062F\u0631 \u0622\u0632\u0645\u0648\u0646\u200C\u0647\u0627\u06CC \u062F\u06A9\u062A\u0631\u06CC \u06F1\u06F3\u06F9\u06F9\u060C \u06F1\u06F4\u06F0\u06F1 \u0648 \u06F1\u06F4\u06F0\u06F3",
        summary: `\u062A\u0639\u0631\u06CC\u0641 \u0639\u062F\u0627\u0644\u062A \u062F\u0631 \u06A9\u0644\u0627\u0645 \u0627\u0645\u06CC\u0631\u0627\u0644\u0645\u0624\u0645\u0646\u06CC\u0646: \xAB\u0627\u0644\u0639\u064E\u062F\u0644\u064F \u06CC\u064E\u0636\u064E\u0639\u064F \u0627\u0644\u0623\u064F\u0645\u0648\u0631\u064E \u0645\u064E\u0648\u0627\u0636\u0650\u0639\u064E\u0647\u0627\xBB (\u0639\u062F\u0627\u0644\u062A \u0642\u0631\u0627\u0631 \u062F\u0627\u062F\u0646 \u0647\u0631 \u0686\u06CC\u0632\u06CC \u062F\u0631 \u062C\u0627\u06CC\u06AF\u0627\u0647 \u0634\u0627\u06CC\u0633\u062A\u0647 \u062E\u0648\u062F \u0627\u0633\u062A).
\u062A\u0645\u0627\u06CC\u0632 \u0639\u062F\u0644 \u0648 \u062C\u0648\u062F: \u0627\u0632 \u062F\u06CC\u062F\u06AF\u0627\u0647 \u0627\u0645\u0627\u0645 \u0639\u0644\u06CC (\u0639)\u060C \u0639\u062F\u0627\u0644\u062A \u0628\u0631\u062A\u0631 \u0627\u0632 \u0628\u062E\u0634\u0634 (\u062C\u0648\u062F) \u0627\u0633\u062A\u060C \u0632\u06CC\u0631\u0627 \u0639\u062F\u0627\u0644\u062A \u0646\u0638\u0645 \u0639\u0645\u0648\u0645\u06CC \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F (\u0633\u0627\u0626\u0633\u064C \u0639\u0627\u0645)\u060C \u062F\u0631\u062D\u0627\u0644\u06CC\u200C\u06A9\u0647 \u0628\u062E\u0634\u0634 \u06CC\u06A9 \u0639\u0627\u0631\u0636\u0647 \u0641\u0631\u062F\u06CC \u0648 \u0645\u0642\u0637\u0639\u06CC \u0627\u0633\u062A (\u0639\u0627\u0631\u0636\u064C \u062E\u0627\u0635).
\u0627\u0635\u0648\u0644 \u0627\u0633\u0627\u0633\u06CC:
\u06F1. \u0627\u0647\u0644\u06CC\u062A \u0648 \u0634\u0627\u06CC\u0633\u062A\u0647\u200C\u0633\u0627\u0644\u0627\u0631\u06CC \u062F\u0631 \u0627\u0646\u062A\u0635\u0627\u0628\u200C\u0647\u0627: \u067E\u0631\u0647\u06CC\u0632 \u0627\u0632 \u062E\u0648\u06CC\u0634\u0627\u0648\u0646\u062F\u0633\u0627\u0644\u0627\u0631\u06CC \u0648 \u0631\u0648\u0627\u0628\u0637 \u062A\u0628\u0627\u0631\u06CC.
\u06F2. \u0628\u0631\u0627\u0628\u0631\u06CC \u062F\u0631 \u0628\u0631\u0627\u0628\u0631 \u0642\u0627\u0646\u0648\u0646: \u062D\u062A\u06CC \u062D\u0627\u06A9\u0645 \u0648 \u06A9\u0627\u0631\u06AF\u0632\u0627\u0631 \u0647\u06CC\u0686 \u0627\u0645\u062A\u06CC\u0627\u0632\u06CC \u062F\u0631 \u0645\u0648\u0627\u062C\u0647\u0647 \u0628\u0627 \u0642\u0648\u0627\u0646\u06CC\u0646 \u0646\u062F\u0627\u0631\u0646\u062F.
\u06F3. \u062A\u0642\u062F\u0645 \u0631\u0636\u0627\u06CC\u062A \u062A\u0648\u062F\u0647 \u0645\u0631\u062F\u0645 \u0628\u0631 \u062E\u0648\u0627\u0635: \u0631\u0636\u0627\u06CC\u062A \u0639\u0645\u0648\u0645 \u0645\u0631\u062F\u0645 \u062E\u0634\u0645 \u062E\u0648\u0627\u0635 \u0631\u0627 \u062C\u0628\u0631\u0627\u0646 \u0645\u06CC\u200C\u06A9\u0646\u062F\u060C \u0627\u0645\u0627 \u062E\u0634\u0645 \u062A\u0648\u062F\u0647\u200C\u0647\u0627 \u0628\u0627 \u0631\u0636\u0627\u06CC\u062A \u0646\u062E\u0628\u06AF\u0627\u0646 \u062F\u0631\u0645\u0627\u0646 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F.`,
