        topic: "\u062A\u062D\u0642\u06CC\u0642 \u062F\u0631 \u0639\u0645\u0644\u06CC\u0627\u062A: \u0631\u0648\u0634 \u0633\u06CC\u0645\u067E\u0644\u06A9\u0633\u060C \u062F\u0648\u06AF\u0627\u0646 (Dual) \u0648 \u062A\u062D\u0644\u06CC\u0644 \u062D\u0633\u0627\u0633\u06CC\u062A",
