        summary: `\u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0631\u06CC\u0632\u06CC \u062E\u0637\u06CC (Linear Programming) \u06CC\u06A9\u06CC \u0627\u0632 \u0627\u0633\u0627\u0633\u06CC\u200C\u062A\u0631\u06CC\u0646 \u0627\u0628\u0632\u0627\u0631\u0647\u0627\u06CC \u0628\u0647\u06CC\u0646\u0647\u200C\u0633\u0627\u0632\u06CC \u062F\u0631 \u0645\u062F\u06CC\u0631\u06CC\u062A \u0635\u0646\u0639\u062A\u06CC \u0627\u0633\u062A:
\u2022 \u0631\u0648\u0634 \u0633\u06CC\u0645\u067E\u0644\u06A9\u0633 (Simplex): \u0627\u0644\u06AF\u0648\u0631\u06CC\u062A\u0645\u06CC \u062A\u06A9\u0631\u0627\u0631\u0634\u0648\u0646\u062F\u0647 \u0628\u0631\u0627\u06CC \u062D\u0631\u06A9\u062A \u0628\u06CC\u0646 \u0646\u0642\u0627\u0637 \u06AF\u0648\u0634\u0647\u200C\u0627\u06CC (Extreme Points) \u0646\u0627\u062D\u06CC\u0647 \u0645\u0648\u062C\u0647 \u062C\u0647\u062A \u062F\u0633\u062A\u06CC\u0627\u0628\u06CC \u0628\u0647 \u0646\u0642\u0637\u0647 \u0628\u0647\u06CC\u0646\u0647.
\u2022 \u062A\u0626\u0648\u0631\u06CC \u062F\u0648\u06AF\u0627\u0646\u06AF\u06CC (Duality Theory): \u0628\u0647 \u0627\u0632\u0627\u06CC \u0647\u0631 \u0645\u0633\u0626\u0644\u0647 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0631\u06CC\u0632\u06CC \u062E\u0637\u06CC \u0627\u0648\u0644\u06CC\u0647 (Primal)\u060C \u06CC\u06A9 \u0645\u0633\u0626\u0644\u0647 \u062B\u0627\u0646\u0648\u06CC\u0647 \u06CC\u0627 \u062F\u0648\u06AF\u0627\u0646 (Dual) \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F.
\u2022 \u0645\u062A\u063A\u06CC\u0631\u0647\u0627\u06CC \u062F\u0648\u06AF\u0627\u0646 \u0627\u0631\u0632\u0634 \u0627\u0642\u062A\u0635\u0627\u062F\u06CC \u06CC\u0627 \u0642\u06CC\u0645\u062A \u0633\u0627\u06CC\u0647 (Shadow Price) \u0647\u0631 \u0648\u0627\u062D\u062F \u0645\u0646\u0628\u0639 \u0645\u062D\u062F\u0648\u062F \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F.
\u2022 \u0642\u0636\u0627\u06CC\u0627\u06CC \u062F\u0648\u06AF\u0627\u0646\u06AF\u06CC:
  \u06F1. \u0642\u0636\u06CC\u0647 \u062F\u0648\u06AF\u0627\u0646\u06AF\u06CC \u0636\u0639\u06CC\u0641: \u0628\u0631\u0627\u06CC \u0647\u0631 \u062C\u0648\u0627\u0628 \u0645\u0648\u062C\u0647 \u0627\u0648\u0644\u06CC\u0647 X \u0648 \u062B\u0627\u0646\u0648\u06CC\u0647 Y \u062F\u0631 \u0645\u0633\u0626\u0644\u0647 \u0645\u0627\u06A9\u0632\u06CC\u0645\u0645\u200C\u0633\u0627\u0632\u06CC\u060C \u0647\u0645\u0648\u0627\u0631\u0647 Z_primal <= W_dual.
  \u06F2. \u0642\u0636\u06CC\u0647 \u062F\u0648\u06AF\u0627\u0646\u06AF\u06CC \u0642\u0648\u06CC: \u0627\u06AF\u0631 \u0627\u0648\u0644\u06CC\u0647 \u062C\u0648\u0627\u0628 \u0628\u0647\u06CC\u0646\u0647 \u0645\u062A\u0646\u0627\u0647\u06CC \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F\u060C \u062B\u0627\u0646\u0648\u06CC\u0647 \u0646\u06CC\u0632 \u062C\u0648\u0627\u0628 \u0628\u0647\u06CC\u0646\u0647 \u062F\u0627\u0631\u062F \u0648 \u0645\u0642\u062F\u0627\u0631 \u0628\u0647\u06CC\u0646\u0647 \u0647\u0631 \u062F\u0648 \u062A\u0627\u0628\u0639 \u0647\u062F\u0641 \u0628\u0631\u0627\u0628\u0631 \u0627\u0633\u062A (Z* = W*).
  \u06F3. \u0642\u0636\u06CC\u0647 \u0627\u0646\u0637\u0628\u0627\u0642 \u0645\u06A9\u0645\u0644 (Complementary Slackness): \u062D\u0627\u0635\u0644\u200C\u0636\u0631\u0628 \u0645\u062A\u063A\u06CC\u0631 \u0627\u0648\u0644\u06CC\u0647 \u062F\u0631 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u062B\u0627\u0646\u0648\u06CC\u0647 \u0645\u062A\u0646\u0627\u0638\u0631 \u0628\u0631\u0627\u0628\u0631 \u0635\u0641\u0631 \u0627\u0633\u062A.`,
        konkoorTips: [
          "\u062F\u0627\u0645 \u0637\u0631\u0627\u062D \u06A9\u0646\u06A9\u0648\u0631: \u0627\u06AF\u0631 \u062F\u0631 \u0645\u0633\u0626\u0644\u0647 \u0627\u0648\u0644\u06CC\u0647 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u0628\u0647 \u0635\u0648\u0631\u062A \u0627\u06A9\u06CC\u062F\u0627\u064B \u0646\u0627\u0645\u0633\u0627\u0648\u06CC \u0628\u0631\u0642\u0631\u0627\u0631 \u0628\u0627\u0634\u062F (\u0627\u0633\u0644\u06A9 \u0645\u062B\u0628\u062A)\u060C \u0645\u062A\u063A\u06CC\u0631 \u062F\u0648\u06AF\u0627\u0646 \u0645\u062A\u0646\u0627\u0638\u0631 \u062F\u0631 \u062C\u062F\u0648\u0644 \u0628\u0647\u06CC\u0646\u0647 \u0627\u0644\u0632\u0627\u0645\u0627\u064B \u0628\u0631\u0627\u0628\u0631 \u0635\u0641\u0631 \u0627\u0633\u062A.",
          "\u0642\u06CC\u0645\u062A \u0633\u0627\u06CC\u0647 (Shadow Price) \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u0628\u0627 \u0627\u0641\u0632\u0627\u06CC\u0634 \u06CC\u06A9 \u0648\u0627\u062D\u062F \u062F\u0631 \u0633\u0645\u062A \u0631\u0627\u0633\u062A \u0645\u062D\u062F\u0648\u062F\u06CC\u062A (RHS)\u060C \u062A\u0627\u0628\u0639 \u0647\u062F\u0641 \u0686\u0642\u062F\u0631 \u0628\u0647\u0628\u0648\u062F \u0645\u06CC\u200C\u06CC\u0627\u0628\u062F.",
          "\u0627\u06AF\u0631 \u0645\u0633\u0626\u0644\u0647 \u0627\u0648\u0644\u06CC\u0647\u200C\u0627\u06CC \u0646\u0627\u0645\u062D\u062F\u0648\u062F (Unbounded) \u0628\u0627\u0634\u062F\u060C \u0645\u0633\u0626\u0644\u0647 \u062F\u0648\u06AF\u0627\u0646 \u062D\u062A\u0645\u0627\u064B \u0646\u0627\u0645\u0648\u062C\u0647 (Infeasible) \u0627\u0633\u062A."
        ],
