          "\u062A\u0641\u0627\u0648\u062A \u0627\u0635\u0644\u06CC TOPSIS \u0648 VIKOR: \u062A\u0627\u067E\u0633\u06CC\u0633 \u0627\u0632 \u0641\u0648\u0627\u0635\u0644 \u0627\u0642\u0644\u06CC\u062F\u0633\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F \u0627\u0645\u0627 \u0648\u06CC\u06A9\u0648\u0631 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0645\u0641\u0647\u0648\u0645 \u0633\u0627\u0632\u0634 \u062E\u0637\u06CC \u0631\u062A\u0628\u0647\u200C\u0628\u0646\u062F\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F."
